var um = result.match(/"url":"([0-9a-f]+)"/);
var enc = um ? um[1] : '';
var out = '';
if (enc) {
  try {
    var resp = java.get('https://image.kalaimg.top/play/min/' + enc, {Referer: 'https://www.kalamanhua.com/'});
    var minHtml = String(resp.body());
    var d1 = minHtml.indexOf('var d="');
    var b64 = '';
    if (d1 >= 0) { var d2 = minHtml.indexOf('"', d1 + 7); if (d2 > d1) { b64 = minHtml.substring(d1 + 7, d2); } }
    var k1 = minHtml.indexOf('k=[');
    var k = [];
    if (k1 >= 0) { var k2 = minHtml.indexOf(']', k1 + 3); if (k2 > k1) { var kp = minHtml.substring(k1 + 3, k2).split(','); for (var t = 0; t < kp.length; t++) { k.push(parseInt(kp[t])); } } }
    if (b64 && k.length > 0) {
      var bytes = java.base64DecodeToByteArray(b64);
      var dec = '';
      for (var i = 0; i < bytes.length; i++) {
        dec += String.fromCharCode((bytes[i] & 0xff) ^ k[i % k.length]);
      }
      var imgs = dec.match(/data-src="\/image\/index\/[^"]+"/g);
      if (imgs) {
        for (var j = 0; j < imgs.length; j++) {
          var src = imgs[j].replace(/data-src="/, '').replace(/"$/, '');
          out += '<img src="https://image.kalaimg.top' + src + ',{"headers":{"Referer":"https://www.kalamanhua.com/"}}">';
        }
      }
    }
  } catch(e) {}
}
out;

